import{_ as t,o,c as a,a3 as n}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"Run local models","description":"Run Ollama / LM Studio / A1111 / ComfyUI on your PC, connect MiniTavern on your phone over LAN (BYOK); entry to local LLM and image-gen tutorials.","frontmatter":{"title":"Run local models","description":"Run Ollama / LM Studio / A1111 / ComfyUI on your PC, connect MiniTavern on your phone over LAN (BYOK); entry to local LLM and image-gen tutorials.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Run local models · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Run Ollama / LM Studio / A1111 / ComfyUI on your PC, connect MiniTavern on your phone over LAN (BYOK); entry to local LLM and image-gen tutorials."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/local"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/local"}]]},"headers":[],"relativePath":"en/local/index.md","filePath":"en/local/index.md","lastUpdated":1787224147000}'),l={name:"en/local/index.md"};function r(d,e,i,s,c,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="run-local-models" tabindex="-1">Run local models <a class="header-anchor" href="#run-local-models" aria-label="Permalink to &quot;Run local models&quot;">​</a></h1><p>MiniTavern is a <strong>BYOK (bring your own key)</strong> client: requests go to the address you configure; it is not locked to one cloud vendor.<br> “Run local models” means running inference on <strong>your own computer</strong>, then connecting MiniTavern on your phone over the local network.</p><p>This section has two tracks:</p><table tabindex="0"><thead><tr><th>Type</th><th>Use</th><th>Entry</th></tr></thead><tbody><tr><td><strong>Language model deploy</strong></td><td>Chat, continue writing, rewrite image prompts</td><td><a href="/ultra_guides/en/quickstart">30-minute quickstart</a> · <a href="/ultra_guides/en/local/tools">Tools overview</a></td></tr><tr><td><strong>Image model deploy</strong></td><td><code>/imagine</code>, attachment image gen, backgrounds</td><td><a href="/ultra_guides/en/local/image-gen/">Image gen overview</a></td></tr></tbody></table><p>No GPU and no desire to install servers? Start with <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a> for trial / free quotas.</p><blockquote><p>MiniTavern <strong>does not run large language or diffusion models on the phone</strong>. Services run on the PC; the App handles character cards, lorebook, chat, and image-gen requests.</p></blockquote><h2 id="language-model-deploy" tabindex="-1">Language model deploy <a class="header-anchor" href="#language-model-deploy" aria-label="Permalink to &quot;Language model deploy&quot;">​</a></h2><p>Run an LLM on the PC (Ollama, LM Studio, KoboldCPP, etc.), then in the App choose <strong>Custom (OpenAI)</strong>.</p><table tabindex="0"><thead><tr><th>Item</th><th>Suggestion</th></tr></thead><tbody><tr><td>PC</td><td>Windows / macOS / Linux; <strong>16GB+</strong> RAM recommended</td></tr><tr><td>GPU (optional)</td><td>NVIDIA / Apple Silicon is faster; CPU-only still works</td></tr><tr><td>Network</td><td>Phone and PC on the same Wi‑Fi (avoid guest/client isolation)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Tool</th><th>Best for</th><th>Default port</th></tr></thead><tbody><tr><td><a href="/ultra_guides/en/ollama/install">Ollama</a></td><td>CLI simplicity, one-command pull</td><td><code>11434</code></td></tr><tr><td><a href="/ultra_guides/en/lmstudio/install">LM Studio</a></td><td>GUI, click-to-download</td><td><code>1234</code></td></tr><tr><td><a href="/ultra_guides/en/koboldcpp/install">KoboldCPP</a></td><td>Popular in roleplay communities</td><td><code>5001</code></td></tr><tr><td><a href="/ultra_guides/en/llamacpp/install">llama.cpp</a></td><td>Run GGUF directly</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/en/localai/install">LocalAI</a></td><td>Docker / all-in-one compatibility layer</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/en/jan/install">Jan</a> · <a href="/ultra_guides/en/textgen/install">text-generation-webui</a></td><td>Other GUIs or plugin ecosystems</td><td>See each page</td></tr></tbody></table><p>Suggested order: <a href="/ultra_guides/en/quickstart">30-minute quickstart</a> → <a href="/ultra_guides/en/local/tools">Tools overview</a> → <a href="/ultra_guides/en/local/models">Recommended models</a> → <a href="/ultra_guides/en/connect-app/minitavern">Configure in MiniTavern</a> → stuck? <a href="/ultra_guides/en/troubleshoot">Troubleshoot</a>.</p><h2 id="image-model-deploy" tabindex="-1">Image model deploy <a class="header-anchor" href="#image-model-deploy" aria-label="Permalink to &quot;Image model deploy&quot;">​</a></h2><p>Run Stable Diffusion–family services on the PC. In the App: <strong>Settings → Image gen → Image gen link</strong> → A1111 or ComfyUI.</p><table tabindex="0"><thead><tr><th>Backend</th><th>Default port</th><th>Guide</th></tr></thead><tbody><tr><td><a href="/ultra_guides/en/local/image-gen/a1111">A1111 / SD WebUI</a></td><td><code>7860</code></td><td>Needs <code>--api --listen</code></td></tr><tr><td><a href="/ultra_guides/en/local/image-gen/comfyui">ComfyUI</a></td><td><code>8188</code> (Desktop often <code>8000</code>)</td><td>Needs <code>--listen</code></td></tr></tbody></table><p>Overview and hardware: <a href="/ultra_guides/en/local/image-gen/">Image model deploy</a>; filling the link: <a href="/ultra_guides/en/local/image-gen/connect-app">Connect App</a>.</p><h2 id="important-reminders" tabindex="-1">Important reminders <a class="header-anchor" href="#important-reminders" aria-label="Permalink to &quot;Important reminders&quot;">​</a></h2><ul><li>The address on the phone must be the PC’s <strong>LAN IP</strong> — <strong>not</strong> <code>localhost</code> / <code>127.0.0.1</code>.</li><li>Language-model Base URLs usually end with <code>/v1</code> (e.g. <code>http://192.168.1.8:11434/v1</code>).</li><li>A1111 image gen needs <code>--api</code>; ComfyUI must be reachable on the LAN.</li><li>Allow the ports in the firewall; do not expose an unauthenticated API to the public internet.</li></ul>',17)])])}const m=t(l,[["render",r]]);export{g as __pageData,m as default};
